// Verifies Collect's signature over the RAW body: t within ±5 min, HMAC-SHA256(secret, t.raw).
// Anything else is answered 401 and never sent.
const crypto = require('crypto');
const item = $input.first();
const raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
const header = (item.json.headers['x-signature'] || '').toString();
const parts = Object.fromEntries(header.split(',').map((p) => p.split('=')));
const t = Number(parts.t);
const expected = crypto.createHmac('sha256', $env.COLLECT_SIGNING_SECRET).update(`${t}.${raw}`).digest('hex');
const fresh = Math.abs(Date.now() / 1000 - t) <= 300;
const ok = fresh && typeof parts.v1 === 'string' && parts.v1.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(parts.v1), Buffer.from(expected));
const body = ok ? JSON.parse(raw) : null;
return [{ json: { ok, mail: body && body.type === 'mail.send' ? body.data : null } }];

// Idempotency (review S-09): Collect retries a mail it may already have handed over (crash
// after the POST) with the SAME Idempotency-Key (= its outbox id). A key seen in the last 7 days
// is answered with the stored result and NOT sent again. Static data of the active workflow.
const store = $getWorkflowStaticData('global');
store.sent = store.sent || {};
const now = Date.now();
for (const [k, v] of Object.entries(store.sent)) {
  if (now - v.at > 7 * 24 * 3600 * 1000) delete store.sent[k];
}
const headers = $('Collect webhook').first().json.headers || {};
const key = (headers['idempotency-key'] || '').toString();
const seen = key ? store.sent[key] : undefined;
return [{ json: { ...$input.first().json, key, duplicate: Boolean(seen), messageId: seen ? seen.messageId : null } }];

// Remember the key only AFTER the mail went out, with the provider's Message-ID.
const store = $getWorkflowStaticData('global');
store.sent = store.sent || {};
const key = $('Already sent?').first().json.key;
const messageId = $input.first().json.messageId || null;
if (key) store.sent[key] = { at: Date.now(), messageId };
return [{ json: { messageId } }];
